  CONSTRAINT `fk_ranking_entries_season` FOREIGN KEY (`season_id`) REFERENCES `ranking_seasons` (`season_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_ranking_entries_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE
