-- Table structure for table `user_concept_progress`
--

DROP TABLE IF EXISTS `user_concept_progress`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user_concept_progress` (
  `user_id` int NOT NULL,
  `concept_id` bigint NOT NULL,
  `status` enum('NOT_STARTED','IN_PROGRESS','COMPLETED','REVIEW_REQUIRED') NOT NULL DEFAULT 'NOT_STARTED',
  `progress_percent` tinyint unsigned NOT NULL DEFAULT '0',
  `last_block_id` bigint DEFAULT NULL,
  `concept_quiz_passed` tinyint(1) DEFAULT NULL,
  `concept_quiz_score` decimal(5,2) DEFAULT NULL,
  `started_at` datetime DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `last_studied_at` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`user_id`,`concept_id`),
  KEY `idx_user_concept_progress_user_status` (`user_id`,`status`,`last_studied_at`),
  KEY `idx_user_concept_progress_concept` (`concept_id`,`status`),
  KEY `fk_user_concept_progress_last_block` (`last_block_id`),
  CONSTRAINT `fk_user_concept_progress_concept` FOREIGN KEY (`concept_id`) REFERENCES `learning_concepts` (`concept_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_user_concept_progress_last_block` FOREIGN KEY (`last_block_id`) REFERENCES `learning_concept_blocks` (`block_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_user_concept_progress_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
